/* bf-9：欢呼换成 6 条新录音、下锅音效新增 9 条 —— 全部纳入规格盘点。
   bf-12 仓库清理：audio/bf/ 下**只留代码点名的 15 个**（9 条 cook_* + 池里 4 条欢呼 + tick + slow），
   其余 78 个旧件已归档到 audio/bf/_unused/（文件一个都没删；下划线前缀目录被 .gitignore
   第 93 行的「audio 下划线前缀」规则排除 → 不入库、不分发，与 audio/mj/_bak_pre_wopeng/ 同一做法）。
   所以这里盘点的就是那 15 个「还在岗」的；归档件在下面单独验「仍在盘上、且没有任何通道引用」。 */
const ARCH = path.join(dir, "_unused");
const at = f => (fs.existsSync(path.join(dir, f)) ? path.join(dir, f) : path.join(ARCH, f));
const want = ["tick.mp3", "slow.mp3",
              "happy_v1.mp3", "happy_v3.mp3", "happy_finally2.mp3", "happy_i45.mp3",
              "cook_congee.mp3", "cook_milk.mp3", "cook_soup.mp3", "cook_egg.mp3",
              "cook_bacon.mp3", "cook_sandwich.mp3", "cook_bun.mp3",
              "cook_salad.mp3", "cook_juice.mp3"];

