/* 欢呼候选 + 一条「太慢了」都要有人声时长（>0.4s），不是空文件。
   bf-12：v2/v4/v5/v6 已归档 → 走 at() 到 _unused/ 里量（归档不等于没内容）。 */
["happy_v1.mp3", "happy_v2.mp3", "happy_v3.mp3", "happy_v4.mp3", "happy_v5.mp3",
 "happy_v6.mp3", "slow.mp3"].forEach(f => {
  const info = mp3info.mp3Info(at(f));
  assert.ok(info.decoded > 0.4, f + " 时长 " + (info.decoded * 1000).toFixed(0) + "ms，像一条语音");
});
/* ── bf-12 仓库清理的两条硬判据 ──────────────────────────────────────────
   ① 归档件一个都没丢，且**没有任何一个**被通道 / 食材音效表引用；
   ② audio/bf/ 根目录下只剩代码点名的 15 个 mp3 —— 「清理干净」不看叙述，看目录。 */
assert.ok(fs.existsSync(ARCH), "归档目录 audio/bf/_unused/ 存在");
const archived = fs.readdirSync(ARCH).filter(f => /\.mp3$/i.test(f));
assert.ok(archived.length >= 70, "_unused/ 里归档件齐全（实际 " + archived.length + " 个）");
archived.forEach(f => {
  assert.equal(R.audio.NAMES.some(n => R.audio.FILES[n].indexOf(f) >= 0), false,
    "归档件 " + f + " 不参与任何播放通道");
  assert.equal(Object.keys(R.audio.COOK_FILES).some(k => R.audio.COOK_FILES[k] === f), false,
    "归档件 " + f + " 不是任何食材的下锅音效");
});
const rootMp3 = fs.readdirSync(dir).filter(f => /\.mp3$/i.test(f)).sort();
assert.equal(rootMp3.length, 15, "audio/bf/ 根目录只剩 15 个在岗素材（实际 " + rootMp3.length + "）");
assert.deepEqual(rootMp3, want.slice().sort(), "剩下的正好就是通道点名的那些");
